import {
  Component,
  ElementRef,
  afterNextRender,
  computed,
  inject,
  input,
  viewChild,
} from '@angular/core';

import { CwKbd } from '@cadenway/ui/components/kbd';

import { KANBAN_BOARD, type KanbanCellView } from '../kanban.token';

/**
 * The quick add of `cw-kanban`, generated by the board at the bottom of a column (or of a cell in
 * swimlanes) when « + », « Ajouter une tâche » or N opens it: a form with one borderless field and
 * the « Entrée créer » hint. Enter emits the board's `created` with the trimmed title and keeps the
 * field open, empty, for the next one; Escape closes it and the focus returns to the column. The
 * field takes the focus when it opens.
 */
@Component({
  selector: 'cw-kanban-quick-add',
  imports: [CwKbd],
  host: { class: 'block' },
  templateUrl: './kanban-quick-add.component.html',
})
export class KanbanQuickAddPart {
  /** The cell the new card goes to. */
  readonly cell = input.required<KanbanCellView>();

  protected readonly board = inject(KANBAN_BOARD);
  private readonly field = viewChild.required<ElementRef<HTMLInputElement>>('field');

  protected readonly formLabel = computed(() =>
    this.board.format(this.board.texts().quickAdd, { column: this.cell().column.label }),
  );

  constructor() {
    afterNextRender(() => {
      this.field().nativeElement.focus();
    });
  }

  protected submit(event: Event): void {
    event.preventDefault();
    const field = this.field().nativeElement;
    this.board.create(field.value, this.cell());
    field.value = '';
  }

  protected close(event: Event): void {
    event.preventDefault();
    event.stopPropagation();
    this.board.closeQuickAdd(this.cell());
  }
}
